{
 "params": {
  "Tf": 4.6251455262117295e-14,
  "m": 0.05902827070187713,
  "n": 0.038323152806975895,
  "Kpv": 0.6773027961472793,
  "Kiv": 1.2024062274181684,
  "w0": 376.99111843077515
 },
 "defs": {
  "vd": "V*cos(delta - theta)",
  "vq": "-V*sin(delta - theta)",
  "vr": "Vset + n*(Q0 - Qf)",
  "Idref": "Kpv*(vr - vd) + xvd",
  "Iqref": "Kpv*(0 - vq) + xvq",
  "Id": "Idref",
  "Iq": "Iqref",
  "Pe": "vd*Id + vq*Iq",
  "Qe": "-vd*Iq + vq*Id"
 },
 "states": {
  "Pf": {
   "rhs": "(Pe - Pf)/Tf",
   "init": "P0"
  },
  "Qf": {
   "rhs": "(Qe - Qf)/Tf",
   "init": "Q0"
  },
  "delta": {
   "rhs": "w0*m*(P0 - Pf)",
   "init": "theta0"
  },
  "xvd": {
   "rhs": "Kiv*(vr - vd)",
   "init": "P0/V0"
  },
  "xvq": {
   "rhs": "Kiv*(0 - vq)",
   "init": "-Q0/V0"
  }
 },
 "outputs": {
  "P": "Pe",
  "Q": "Qe"
 },
 "notes": "structure_menu blocks: {\"pf\": \"droop\", \"qv\": \"droop\", \"voltage\": \"pi_voltage_loop\", \"inner\": \"ideal\"}"
}
